import styles from "./accommodation-list-item.module.less";
import Label from "@/core/components/primitives/label/label";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";
import { ExistingThemes } from "@/core/types/existing-themes";
import Icon from "@/core/components/primitives/icon/icon";

export type AccommodationListItemProps = {
  image: {
    gatsbyImageData: IGatsbyImageData;
  };
  title: string;
  priceExample: string;
  size: string;
  numberOfPeople: string;
  numberOfNights: string;
  label?: string;
  componentTheme?: ExistingThemes;
};

export const AccommodationListItem = ({
  image,
  title,
  priceExample,
  size,
  numberOfPeople,
  numberOfNights,
  label,
  componentTheme = "",
}: AccommodationListItemProps) => {
  return (
    <article className={[styles.wrapper, componentTheme].join(" ")}>
      <div className={styles.imageWrapper}>
        {image && image.gatsbyImageData && (
          <GatsbyImage image={image.gatsbyImageData} alt={title} className={styles.listImage} />
        )}
        {label && (
          <div className={styles.labelWrapper}>
            <Label title={label} />
          </div>
        )}
      </div>
      <div className={styles.textWrapper}>
        {title && <h4 className={styles.headline}>{title}</h4>}
        <div className={styles.propertiesWrapper}>
          <div className={styles.propertyRow}>
            <Icon name="credit-card" size="l" />
            <p className={[styles.propertyValue, "body-s"].join(" ")}>{priceExample}</p>
          </div>
          <div className={[styles.propertyRow].join(" ")}>
            <Icon name="square-foot" size="l" />
            <p className={[styles.propertyValue, "body-s"].join(" ")}>{size}</p>
          </div>
          <div className={[styles.propertyRow].join(" ")}>
            <Icon name="group" size="l" />
            <p className={[styles.propertyValue, "body-s"].join(" ")}>{numberOfPeople}</p>
          </div>
          <div className={[styles.propertyRow].join(" ")}>
            <Icon name="nights" size="l" />
            <p className={[styles.propertyValue, "body-s"].join(" ")}>{numberOfNights}</p>
          </div>
        </div>
      </div>
    </article>
  );
};
